 def __init__(self):super().__init__();self.ids=[];self.rows=0;self.groups=0
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if tag=='tr':self.rows+=1
  if tag=='g':self.groups+=1
